export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "17:10。M 區。走廊。摺疊桌被重新排成 U 形。筆電打開。螢幕上是決策介面。活動接收者依存圖。代碼。狀態欄。沒有名字。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪站在 U 形桌的開口處。她沒有坐下。她看著螢幕。看著那些代碼。M-00。G07／03。高依存遠端單元 B。LEGACY／02。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的聲音不高。但很清楚。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "決策介面。恢復 HUMAN 欄。恢復年齡帶。恢復成人／未成年人標示。恢復醫療風險欄。恢復不可逆風險標記。恢復法定代理人欄。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她頓了一下。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "M-00——朝倉紗英。依法顯示。她是我的母親。我是家屬。我有權要求她的名字出現在決策介面上。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "其他姓名——依合法範圍處理。我不要求看見所有受試者的私人資料。我要求——介面至少顯示 HUMAN、成人或未成年人、年齡帶、是否有法定代理人、已知醫療狀態、不可逆風險、依法可向家屬或調查開示的姓名。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "指定專家的手停在鍵盤上。他看了一眼日下部。日下部點頭。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "技術上可行。決策介面可以恢復人類身分欄。不影響候選封存。不影響評估結果。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他開始操作。螢幕上的依存圖開始變化。代碼旁邊出現了新的欄位。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "M-00——HUMAN／ADULT／46／法定代理人：無／醫療狀態：高度依賴雙向閉環／不可逆風險：死亡、深度昏迷、神經崩潰。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "然後是名字。M-00——朝倉紗英。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪看著那個名字出現在螢幕上。在代碼旁邊。在風險欄旁邊。在 HUMAN 標記旁邊。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）母親。名字回來了。不是代碼。不是 M-00。是朝倉紗英。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她看著螢幕。那個名字在代碼旁邊。在風險欄旁邊。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她在那裡。在螢幕上。在四個紅區裡。名字回來了——可是她還在閉環上。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "17:15。螢幕繼續更新。G07／03——HUMAN／MINOR／13／法定代理人：有／醫療狀態：長期意識障礙、REMOTE CAL ACTIVE／不可逆風險：嚴重生理波動、癲癇樣放電。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "高依存遠端單元 B——HUMAN／MINOR／姓名依法遮蔽／法定代理人：有／醫療狀態：歷史切換時長時間癲癇樣放電／不可逆風險：中斷不可接受。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "LEGACY／02——HUMAN／年齡帶依法遮蔽／法定代理人：依狀態判定／醫療狀態：唯一穩定源為 M-00、本地模型已退役／不可逆風險：長時間失語及意識障礙。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "四個紅區。四個活人。現在——螢幕上有了 HUMAN。有了年齡帶。有了成人或未成年人。有了醫療風險。有了不可逆風險。有了依法可開示的姓名。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "不再是只有代碼。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "17:20。澪看著螢幕。她看了一會兒。然後她轉向日下部。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "我提交正式反對。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部遞過來一張表格。正式反對書。澪接過筆。她的字很穩。不是不抖。是用力壓住了。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她在表格上寫了一行。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "若一個方案只有在人的身分被隱藏後才能執行，它不得被預先授權。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她放下筆。看著那行字。然後她簽了名。朝倉澪。日期。時間。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部接過表格。看了一遍。然後他把它放進證物套。封存。編號。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "正式反對。已受理。進入臨時共同安全會議記錄。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "17:25。走廊裡的人開始增加。不是研究人員。是外部人員。公共營運方系統安全負責人。外部醫療主管。東京及茨城警方代表。司法證據保全人員。TKS 合規與安全代表。兒少權利與倫理代表。主管機關代表。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "凪原走到 U 形桌的一側。她的身後跟著內閣法律顧問。白袍。銀框眼鏡。脊椎沒有彎。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "千田坐在技術證人席。他的面前放著 R2 文件副本和閉環圖。他沒有翻開。他只是坐著。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪坐在被指向作者與家屬陳述人席。她的面前放著那張正式反對書的副本。她沒有碰它。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "17:30。日下部站在 U 形桌的頭部。他的聲音回到程序模式。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "臨時共同安全會議。出席——公共營運方系統安全負責人。外部醫療主管。東京及茨城警方與司法證據保全。TKS 合規與安全。兒少權利與倫理代表。主管機關與凪原方代表。千田浩介作技術證人。朝倉澪作被指向作者與家屬陳述人。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "議題——R4 約束式重建結果。失敗包絡。四個紅區。未來作者元資料。澪的正式反對。R4 的臨時狀態。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他看著所有人。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "程序。技術證人先報告重建結果。未來資料組報告元資料。家屬陳述人報告正式反對。各方回應。最後表決 R4 臨時狀態。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "17:35。千田站起來。他的聲音不高。但很清楚。他把閉環圖翻開。指著共用段。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "R4 約束式重建。三個方案家族。A——完整安全切離。B——保留過濾延後提交。C——閉環硬切。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "C 家族與 Chapter 21 元資料高度吻合。MIO／SAW COST／ACCEPTED／ONCE。看見代價仍接受。C 家族的代價——M-00 與遠端高依存單元失去雙向穩定閉環——是所有家族中最明確的個體風險。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他頓了一下。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "R4 高可信路線。第一步——先將 G07／12 完成安全切離。悠真。已完成。SAFE／DETACHED。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "其餘步驟——取得缺失載體。進入 KAGAMI-01 本地維護授權。保留原始過濾至最後可控狀態。在 CONSENSUS COMMIT 前嘗試隔離一致性層。若邏輯隔離無法驗證——切斷共用 CAL／PHASE 閉環。阻斷公共 fanout。使本地簽署鏈失效。不等待其他活動接收者建立本地影子參照。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他放下圖。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "R4 可能高概率阻止——一致性層完成公共擴散。下一個回聲窗依既定設定運作。VALIDATION COHORT 異常一致化繼續擴大。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "代價——M-00。高依存 G07。舊接收單元。失去穩定閉環。四個紅區。四個活人。均跨越不可逆嚴重傷害門檻。部分情境包含死亡。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他坐下了。沒有人接話。但所有人都聽到了。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "17:45。獨立神經心理專業人員報告未來資料組。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.NeuropsychProfessional, character: "獨立神經心理專業人員", dialogue: "Chapter 21 既有元資料。R4／AUTHOR／MIO。FULL PACKAGE／NO ESCROW。MIO／SAW COST／ACCEPTED／ONCE。來源——紗英臨床觀察記錄。不是客觀事實陳述。來源未定。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.NeuropsychProfessional, character: "獨立神經心理專業人員", dialogue: "澪主觀前向回聲——另封。標記非證據。只用於一致性比對。不參與候選生成。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她頓了一下。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.NeuropsychProfessional, character: "獨立神經心理專業人員", dialogue: "一致性比對結果——主觀回聲中的「悠真第一順位」與 R4 路線第一步一致。「不要送回完整方案」與 FULL PACKAGE／NO ESCROW 一致。一致性成立。但一致性不等於驗證。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "17:50。日下部看向澪。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "家屬陳述人。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪站起來。她的膝蓋還是有點僵。但她站直了。她看著 U 形桌兩側的所有人。系統安全。外部醫療。警方。司法。TKS。兒少。主管機關。凪原。千田。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她沒有提高聲音。她沒有激動。她的聲音和她在查核報告裡寫字時一樣——精準。節制。不誇張。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "R4 的作者知道 M-00 是朝倉紗英。這是時間順序的必然。我不否認。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "她先救了悠真。然後接受了代價。包括母親。一次。我也不否認。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "但我提交正式反對。若一個方案只有在人的身分被隱藏後才能執行，它不得被預先授權。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她頓了一下。她的手指碰了一下桌上的反對書副本。沒有用力。只是碰了一下。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "R4 的決策介面——剛才只有代碼。沒有名字。沒有年齡。沒有成人或未成年人。沒有醫療風險。沒有不可逆風險。沒有法定代理人。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "如果介面上只有代碼——做決定的人看不到人。看不到年齡。看不到未成年人。看不到母親。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "看不到——就不算選擇。那只是參數調整。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "走廊裡沒有聲音。外部醫師停了筆。兒少權利代表看著澪。她的眼睛沒有移開。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "我不要求永久禁止所有緊急硬切。我知道——如果未來出現全新、已證實、即時的大規模死亡風險——必須由當時的多方人員重新決策。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "我要求的是——R4 不得成為預設方案。不得被預先授權。不得自動執行。不得因為倒數開始就直接採用。不得以「未來澪已接受」作為授權。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她看著凪原。凪原的臉沒有變。銀框眼鏡。白袍。脊椎沒有彎。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "未來的我接受過一次。一次。不是永遠。不是預設。不是授權。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她坐下了。沒有人接話。但所有人都聽到了。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "18:00。各方回應開始。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "外部醫療主管先發言。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "外部醫療組確認——四個紅區均為活人。均為 HUMAN。中斷風險不可接受。醫療層面不反對 R4 被標記為 NOT PRE-AUTHORIZED。若未來需要緊急硬切——必須重新進行醫療評估。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "兒少權利代表發言。相原真帆。她的聲音短。平靜。不可動搖。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AharaMaho, character: "相原真帆", dialogue: "四個紅區中兩名為未成年人。G07／03——十三歲。高依存遠端單元 B——未成年人。姓名依法遮蔽。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AharaMaho_Base },
    { characterId: CharacterId.AharaMaho, character: "相原真帆", dialogue: "未成年人及無法表達意願者——必須有獨立醫療與法定代理程序。不得被預先寫入代價。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AharaMaho_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她頓了一下。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AharaMaho, character: "相原真帆", dialogue: "兒少權利代表支持——R4 不得預先授權。未成年人不得在身分被遮蔽的條件下被預先接受為代價。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AharaMaho_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "TKS 合規代表發言。聲音制式。不帶情緒。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.TksLegal, character: "TKS法務", dialogue: "TKS 合規與安全確認——R4 不涉及現行 TKS 公共安全產品線。若 R4 被標記為 FORENSIC／FAILURE-MODE ONLY——不影響現行公共安全系統運作。不反對。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "18:10。主管機關代表。凪原。她站起來。她的聲音和往常一樣——學術。精確。不帶情緒。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.NagiharaYui, character: "凪原唯", dialogue: "R4 的失敗包絡技術上成立。在可能未來中——A 路線無法及時完成。B 路線被覆蓋。commit 逼近。公共異常開始一致化。R4 是唯一能高概率阻止 fanout 的候選。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.NagiharaYui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她頓了一下。她的眼睛掃過 U 形桌兩側。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.NagiharaYui, character: "凪原唯", dialogue: "我不否認——R4 與我十年前的決策邏輯相似。真實且迫近的公共風險。倒數。個體被改寫為代碼。必要犧牲。只例外一次。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.NagiharaYui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的聲音沒有變。但她的語速慢了一拍。只有一拍。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.NagiharaYui, character: "凪原唯", dialogue: "差異只在——各自先把誰從代價裡拿走。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.NagiharaYui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "走廊裡安靜了一瞬。不是因為她承認了什麼。是因為她說出了「必要犧牲」和「只例外一次」——用她自己的聲音。在正式會議記錄裡。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "然後她繼續。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.NagiharaYui, character: "凪原唯", dialogue: "但——若未來出現全新、已證實、即時的大規模死亡風險——必須由當時的多方人員重新決策。不得以「未來澪已接受」作授權。不得由倒數自動替人作決定。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.NagiharaYui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她頓了一下。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.NagiharaYui, character: "凪原唯", dialogue: "主管機關接受——R4 不得預先授權。保留——若未來出現新、已證實的即時災難，仍需重新決策。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.NagiharaYui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她坐下了。她的臉沒有變。但她的手——左手——從桌面收回到膝蓋上。很小的動作。像在收起什麼。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "18:20。日下部看著所有人。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "表決。R4 臨時狀態。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他念出四行。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "R4／RECONSTRUCTED。INTERIM STATUS——NOT PRE-AUTHORIZED。USE——FORENSIC／FAILURE-MODE ONLY。REVIEW——EVENT-TRIGGERED ONLY。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他看著每一方。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "公共營運方系統安全。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "同意。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "外部醫療主管。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "同意。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "東京及茨城警方與司法證據保全。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "警方代表點頭。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "TKS 合規與安全。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.TksLegal, character: "TKS法務", dialogue: "同意。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "兒少權利與倫理代表。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AharaMaho, character: "相原真帆", dialogue: "同意。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AharaMaho_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "主管機關與凪原方代表。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.NagiharaYui, character: "凪原唯", dialogue: "同意。保留——新危機重新決策。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.NagiharaYui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部在表格上寫下最後一行。簽名。時間戳。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "臨時共同安全會議決議——R4／RECONSTRUCTED。INTERIM STATUS——NOT PRE-AUTHORIZED。USE——FORENSIC／FAILURE-MODE ONLY。REVIEW——EVENT-TRIGGERED ONLY。全體同意。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "18:25。走廊裡沒有掌聲。沒有鬆一口氣的聲音。只有椅子被推回的聲音。文件被收進資料袋的聲音。筆電被合上的聲音。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪坐在原位。她沒有站起來。她看著桌上那份反對書副本。她看著那行字。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "若一個方案只有在人的身分被隱藏後才能執行，它不得被預先授權。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）不是勝利。不是「R4 被取消了」。是「R4 不得被預先授權」。差別很大。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "走廊裡的人還在收拾。椅子。文件。筆電。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）如果未來真的走到只剩幾秒——R4 還是會被重新提出來。還是會被重新決策。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的手指碰了一下桌面上那份副本的邊角。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）可是——不能預先。不能自動。不能因為倒數就替人決定。不能因為「未來的我接受過」就當作授權。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "螢幕暗了。但白板上的字還在。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）這不是禁止。是——不允許在還有時間的時候就先放棄那些人。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "18:30。日下部走到澪面前。他遞了一張紙。澪的書面聲明格式。除了那句核心聲明，下面還有七條。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "妳的書面聲明。七條附加要求。需要確認。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪接過來。她看著那七條。她的字。她的要求。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "第一。所有活動單元完成最低限度人類身分標記。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "第二。未成年人及無法表達意願者——有獨立醫療與法定代理程序。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "第三。高依存單元——先建立本地影子參照。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "第四。原始過濾與一致性層——安全分離。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "第五。公共 fanout——保持禁用。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "第六。缺失原始簽署載體——回收或失效。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "第七。不得再以新接收者作永久 Mother Reference。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她放下紙。看著日下部。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "這七條——不是要求看見所有受試者的私人資料。是要求——做決定的人至少看得到 HUMAN。看得到成人或未成年人。看得到年齡帶。看得到法定代理人。看得到醫療狀態。看得到不可逆風險。看得到依法可開示的姓名。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "把名字補回去——不等於把所有人的隱私交給我。等於——不允許在看不到人的情況下把人寫成代價。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部接過那張紙。看了一遍。然後他把它放進證物套。封存。編號。簽名。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "書面聲明。七條附加要求。已受理。進入會議記錄。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "18:35。會議記錄被列印。各方簽名。外部醫療主管簽名。兒少權利代表簽名。TKS 合規簽名。警方代表簽名。主管機關代表——凪原——簽名。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "凪原簽名的時候，她的筆觸沒有猶豫。她的字和她說話一樣——精確。工整。不帶情緒。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "但簽完以後，她的筆在紙上多停了一秒。只有一秒。然後她放下筆。站起來。回到牆邊。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她簽了。她簽了 NOT PRE-AUTHORIZED。她沒有拒絕。她沒有否決。可是她的筆多停了一秒。那一秒——她在想什麼。她在想函館嗎。她在想——如果十年前也有人要求她把名字補回去——她會簽嗎。我不知道。我只知道——她簽了。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "18:40。走廊裡的人開始散去。外部人員離開。警方收起文件。TKS 合規關上筆電。兒少權利代表收拾資料袋。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "千田走到澪面前。他沒有坐下。他站著。他的聲音很低。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "R4 不是被取消了。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "我知道。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "它被標記為 FORENSIC／FAILURE-MODE ONLY。只能用於失敗模式分析。不能預先授權。不能自動執行。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "我知道。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "如果未來真的走到那個時點——", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "到那個時點——由當時的人重新決策。不是由倒數替人決定。不是由「未來的我接受過」替人決定。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "千田看著她。他的臉很疲憊。但他的眼睛沒有閃避。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "妳知道——到那個時點，重新決策的結果可能還是一樣。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "可能。⋯⋯可是——到那個時點做決定的人——會看到名字。會看到年齡。會看到未成年人。會看到母親。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "看到了——還是選擇——和看不到就接受——不一樣。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "千田沒有接話。他點了一下頭。然後他走回技術證人席。收拾他的文件。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "18:45。走廊裡只剩下幾個人。日下部。澪。凪原。內閣法律顧問。獨立神經心理專業人員。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部把會議記錄的最後一份副本遞給澪。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "妳的副本。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪接過來。她看著封面。臨時共同安全會議。R4 臨時狀態。NOT PRE-AUTHORIZED。FORENSIC／FAILURE-MODE ONLY。EVENT-TRIGGERED ONLY。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她翻開第一頁。她的書面聲明在第三頁。若一個方案只有在人的身分被隱藏後才能執行，它不得被預先授權。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "七條附加要求在第四頁。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "各方簽名在最後一頁。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她合上文件。她沒有把它放進袋子。她拿在手裡。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）不得預先授權。不是禁止。是——不允許在還有時間的時候就先放棄那些人。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "文件拿在手裡。封面上的字。NOT PRE-AUTHORIZED。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）不允許在還沒有走到只剩幾秒的時候就先把名字關掉。不允許用「未來的我接受過」當理由。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的目光落在螢幕上。母親的名字還在那裡。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）未來的我接受過一次。一次。她接受以後——要求不要把方案送回來。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "會議室裡很安靜。空調的聲音填滿了沉默。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她不是留下答案。是留下拒絕答案的自由。現在的我——用那個自由做了什麼。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她看著手裡的文件。七條附加要求。第四頁。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）不是取消 R4。是——不讓 R4 變成預設。不讓未撤離者變成預先寫好的代價。不讓母親的名字在還沒有人看過的時候就被劃掉。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "19:00。走廊。螢光燈。U 形桌被拆回摺疊桌。筆電合上。螢幕暗了。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "凪原站在走廊那端。她還沒有走。她的身後站著內閣法律顧問。白袍。銀框眼鏡。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她看著澪。澪也看著她。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "兩個人之間隔著整條走廊。十公尺。螢光燈。呼吸器的節奏從觀察窗後面傳過來。很慢。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她把母親維持成 M-00。十年。我剛才要求把名字補回去。她簽了。她沒有否決。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "十公尺。螢光燈。呼吸器的節奏。很慢。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）可是——她也不認為自己錯了。她只是——在這一次——接受了不預先授權。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "凪原的脊椎沒有彎。白袍。銀框眼鏡。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）下一次呢。如果新的危機出現。如果倒數開始。如果又走到只剩幾秒。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "走廊裡沒有別的聲音。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她會不會又把人變成代碼。我不知道。她也不知道。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的目光回到白板。四個代碼。四個名字。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）可是——至少這一次——名字在螢幕上。做決定的人會看到 HUMAN。會看到未成年人。會看到母親。至少這一次——不是在看不到人的情況下把人寫成代價。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "19:10。凪原轉身。她的步伐很穩。白袍的下擺沒有晃。內閣法律顧問跟在她後面。她們走向走廊盡頭。走向出口。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪看著她的背影。白袍。銀框眼鏡的反光。脊椎沒有彎。像從走進這棟建築到離開，她的姿勢就沒有變過一次。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "然後她不見了。走廊盡頭的門關上。螢光燈還亮著。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "19:15。日下部走到澪旁邊。他的聲音很低。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "會議記錄。正式反對。書面聲明。七條附加要求。全部封存。全部進入程序。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "⋯⋯嗯。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "下一步——追查缺失載體。attestation。美空節點。維護入口。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "⋯⋯我知道。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "先休息。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪看著他。他的臉很疲憊。眼下的陰影很深。但他的眼睛是清醒的。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "⋯⋯嗯。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她沒有動。她坐在那裡。手裡拿著會議記錄。看著走廊。看著螢光燈。看著觀察窗後面呼吸器的節奏。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）不得預先授權。五個字。不是「禁止」。不是「取消」。是「不得預先」。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "觀察窗後面。呼吸器。很慢。很穩。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）意思是——不能在還有時間的時候就先決定那些人可以死。不能在還沒有看到名字的時候就先接受代價。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的手握著會議記錄。封面上的字。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）不能因為未來的我走過那條路——就當作現在的我也要走。未來的我接受了。一次。現在的我——不接受預先接受。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "走廊。螢光燈。很安靜。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）如果真的走到那個時點——由當時的人重新決策。可是現在——現在還有時間。現在還沒有走到只剩幾秒。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的目光落在白板上。M-00。朝倉紗英。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）現在——名字在螢幕上。母親的名字在螢幕上。現在——不允許把它關掉。", background: Background.Chapter_22_Ch22_Act6_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "19:30。走廊。空了。摺疊桌靠牆。螢幕暗了。只有觀察窗後面的呼吸器還在。很慢。很穩。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪站起來。她的膝蓋很僵。她的手握著會議記錄。她走向走廊盡頭。走向出口。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她走了幾步。然後她停了。她回頭。看了一眼白板。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "白板上的字還沒有被擦掉。四個紅區。四個代碼。M-00。G07／03。高依存遠端單元 B。LEGACY／02。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "但代碼旁邊——現在有了名字。有了 HUMAN。有了年齡帶。有了未成年人。有了醫療風險。有了不可逆風險。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "M-00——朝倉紗英。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "名字在白板上。在螢幕上。在會議記錄裡。在正式反對書裡。在七條附加要求裡。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "不得預先授權。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪轉回頭。她繼續走。走廊盡頭的門開了。走廊外面的光進來了。不是螢光燈。是傍晚的光。很暗。但是真的。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "20:00。M 區。走廊。空了。白板上的字還在。", background: Background.Chapter_22_Ch22_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "距下一次星期一 06:13——約三日十小時十三分鐘。", background: Background.Chapter_22_Ch22_Act6_S0 },
];
